import 'package:flutter/material.dart';
class OrderConfirmationScreen extends StatelessWidget { final String orderId; final double total; const OrderConfirmationScreen({super.key,required this.orderId,required this.total}); @override Widget build(BuildContext c)=>Scaffold(body:Center(child:Padding(padding:const EdgeInsets.all(24),child:Column(mainAxisSize:MainAxisSize.min,children:[const Icon(Icons.check_circle,color:Colors.green,size:90),const SizedBox(height:16),const Text('Order placed successfully!',style:TextStyle(fontSize:22,fontWeight:FontWeight.bold)),const SizedBox(height:8),Text('Order #$orderId\nTotal: ₹${total.toStringAsFixed(0)}',textAlign:TextAlign.center),const SizedBox(height:24),FilledButton(onPressed:()=>Navigator.pushNamedAndRemoveUntil(c,'/home',(_)=>false),child:const Text('Continue shopping'))])));}
